# Tabela 4.1.2 (Situação do Documento). The codes whose C100 carries only the
# identification fields and no child register (Guia Prático, C100, Exceção 1).
COD_SIT_WITHOUT_VALUES = ("02", "03", "04", "05")
COD_SIT_VALID = ("00", "01", "02", "03", "04", "05", "06", "07", "08")
# Guia Prático, E110 campos 02 e 03: extemporaneous documents (Tabela 4.1.2)
# stay out of the debits and go to DEB_ESP.
COD_SIT_EXTEMPORANEOUS = ("01", "07", "10")

# state_edoc -> COD_SIT when the document has no state_fiscal of its own.
COD_SIT_FROM_EDOC = {
    "cancelada": "02",
    "denegada": "04",
    "inutilizada": "05",
}


def cod_sit(document):
    """COD_SIT of a fiscal document (Tabela 4.1.2).

    `state_fiscal` is the user's word and wins when it carries a code of the
    table. In practice it is only written by the cancellation (02/03), so an
    authorized NF-e usually has it empty: the situation then comes from the
    electronic document itself (cancelled, denied, number voided) and, for a
    regular one, from its purpose (complementary NF-e is 06). Leaving the field
    blank makes the PVA refuse every C100 ("campo obrigatório").
    """
    if document.state_fiscal in COD_SIT_VALID:
        return document.state_fiscal
    if document.state_edoc in COD_SIT_FROM_EDOC:
        return COD_SIT_FROM_EDOC[document.state_edoc]
    if document.edoc_purpose == "2":
        return "06"
    return "00"


def import_document_code(number):
    """C120.COD_DOC_IMP from the number of the import declaration.

    Layout 020 (NT 2025.001) adds 2 = DUIMP. The DUIMP number has the format
    "AABR" + 11 digits (e.g. 26BR00012345678), while a DI is 10 digits only;
    the NF-e carries both in the same `nDI` tag.
    """
    if re.match(r"^\d{2}BR\d+$", (number or "").upper()):
        return "2"
    return "0"


def sped_phone(phone):
    """FONE of 0005/0100: area code plus number, 11 positions at most.

    The partner usually also stores the country code, which does not fit and
    is not asked for: Brazil's 55 is dropped, only when the number would not
    fit. A partner with no phone gives an empty field instead of an error.
    """
    phone = (phone or "").split(",")[0].strip()
    phone = misc.punctuation_rm(phone).replace(" ", "")
    if len(phone) > 11 and phone.startswith("55"):
        phone = phone[2:]
    return phone


def bookkept_documents(env, declaration):
    """The documents that get a C100 (see RegistroC100._odoo_domain)."""
    domain = env["l10n_br_sped.efd_icms_ipi.c100"]._odoo_domain(None, declaration)
    return env["l10n_br_fiscal.document"].search(domain)


def valued_documents(env, declaration):
    """Bookkept documents with values: not cancelled, denied or voided."""
    return bookkept_documents(env, declaration).filtered(
        lambda doc: cod_sit(doc) not in COD_SIT_WITHOUT_VALUES
    )


def has_items(document):
    """Whether the document is written with its items (C170).

    Guia Prático, C100, Exceção 2: an NF-e/NFC-e issued by the taxpayer goes
    out as C100 + C190 only.
    """
    return not (
        document.issuer == DOCUMENT_ISSUER_COMPANY
        and document.document_type_id.code in ("55", "65")
    )


def item_lines(env, declaration):
    """The lines that become a C170: the only ones 0200/0190/0400 serve.

    The PVA refuses an item, a unit or a nature of operation that no other
    register references ("não informar ... se não referenciado"), so the
    tables of block 0 follow the C170, not every line of the period.
    """
    documents = valued_documents(env, declaration).filtered(has_items)
    return documents.mapped("fiscal_line_ids")


def ipi_cst(line):
    """CST_IPI on the taxpayer's side of the operation.

    An entry (CFOP 1/2/3) takes a CST below 50 and an exit one from 50 up
    (Guia Prático, C170 campo 20). A third party's NF-e brings the CST of the
    supplier's exit: 50..55 become 00..05 and 99 becomes 49.
    """
    code = line.ipi_cst_id.code or ""
    cfop = line.cfop_id.code or ""
    if code.isdigit() and cfop[:1] in ("1", "2", "3") and int(code) >= 50:
        return "49" if code == "99" else f"{int(code) - 50:02d}"
    return code


ST_RETURN_CFOPS = (
    "1410", "1411", "1414", "1415", "1660", "1661", "1662",
    "2410", "2411", "2414", "2415", "2660", "2661", "2662",
)  # fmt: skip
ST_REFUND_CFOPS = ("1603", "2603")


def st_by_uf(env, declaration):
    """ICMS-ST of the period per UF, read from the documents (E200/E210).

    Guia Prático, E210: the retention (08) is the C190.VL_ICMS_ST of CFOP 5/6,
    the returns (04) and refunds (05) those of the listed CFOPs and the other
    credits (06) the remaining entries; the UF is the one of the C100
    participant. The PVA cross checks every one of them against the C190, so
    they are summed from the very same lines.
    """
    totals = {}
    for document in valued_documents(env, declaration):
        uf = document.partner_id.state_id.code or declaration.company_id.state_id.code
        for line in document.fiscal_line_ids:
            value = line.icmsst_value
            if not value:
                continue
            cfop = line.cfop_id.code or ""
            bucket = totals.setdefault(
                uf, {"retention": 0.0, "return": 0.0, "refund": 0.0, "other": 0.0}
            )
            if cfop[:1] in ("5", "6"):
                bucket["retention"] += value
            elif cfop in ST_RETURN_CFOPS:
                bucket["return"] += value
            elif cfop in ST_REFUND_CFOPS:
                bucket["refund"] += value
            elif cfop[:1] in ("1", "2"):
                bucket["other"] += value
    return totals


def st_assessment(bucket):
    """E210 fields 03..15 from the period totals of one UF."""
    credits = bucket["return"] + bucket["refund"] + bucket["other"]
    debit = bucket["retention"]
    balance = debit - credits
    return {
        "VL_SLD_CRED_ANT_ST": 0.0,
        "VL_DEVOL_ST": bucket["return"],
        "VL_RESSARC_ST": bucket["refund"],
        "VL_OUT_CRED_ST": bucket["other"],
        "VL_AJ_CREDITOS_ST": 0.0,
        "VL_RETENCAO_ST": debit,
        "VL_OUT_DEB_ST": 0.0,
        "VL_AJ_DEBITOS_ST": 0.0,
        "VL_SLD_DEV_ANT_ST": max(balance, 0.0),
        "VL_DEDUCOES_ST": 0.0,
        "VL_ICMS_RECOL_ST": max(balance, 0.0),
        "VL_SLD_CRED_ST_TRANSPORTAR": max(-balance, 0.0),
        "DEB_ESP_ST": 0.0,
    }


def icms_document_totals(env, declaration):
    """ICMS debits, credits and extemporaneous amounts of the period.

    Guia Prático 3.2.4, E110:
    - campo 02 is the VL_ICMS of the C190 of the exit documents, without the
      extemporaneous ones (COD_SIT 01, 07 and 10) and without CFOP 5605, and
      with CFOP 1605 (debit balance received from another establishment);
    - campo 06 is the VL_ICMS of the C190 of the entry documents, without
      CFOP 1605 and with CFOP 5605;
    - the extemporaneous documents go to campo 15 (DEB_ESP), "acompanhado
      dos demais valores extra-apuração" (campo 03).
    The PVA checks fields 02 and 06 against the C190, so they are read from
    the same documents and lines, never from the accounting: an entry whose
    ICMS went to cost, or an invoice whose tax line differs from its
    document, would otherwise give a file the PVA refuses.
    """
    totals = {"debit": 0.0, "credit": 0.0, "extemporaneous": 0.0}
    for document in valued_documents(env, declaration):
        extemporaneous = cod_sit(document) in COD_SIT_EXTEMPORANEOUS
        for line in document.fiscal_line_ids:
            cfop = line.cfop_id.code or ""
            exit_side = document.fiscal_operation_type != FISCAL_IN
            if cfop == "5605":
                exit_side = False
            elif cfop == "1605":
                exit_side = True
            if exit_side and extemporaneous:
                totals["extemporaneous"] += line.icms_value
            elif exit_side:
                totals["debit"] += line.icms_value
            else:
                totals["credit"] += line.icms_value
    return totals


def e110_values(env, declaration, assessment):
    """The E110 fields: documents for 02/06, the assessment for the rest.

    Debits and credits come from the documents (`icms_document_totals`). The
    assessment contributes what only it knows: the manual adjustments with a
    table 5.1.1 code (fields 04, 05, 08 and 09, also written as E111), the
    credit balance carried from the previous period (10), the deductions (12)
    and the special debits (14). Its own debit and credit lines, read from the
    accounting, are deliberately left out: they describe the same operations
    the documents do, and adding both would count them twice.
    """
    documents = icms_document_totals(env, declaration)
    manual = dict.fromkeys(
        ("adjustment_debit", "adjustment_credit", "credit_reversal", "debit_reversal"),
        0.0,
    )
    for line in assessment.line_ids.filtered(lambda line: line.source == "manual"):
        key = assessment._total_key_for_line(line)
        if key in manual:
            manual[key] += line.tax_amount
    debit_side = (
        documents["debit"] + manual["adjustment_debit"] + manual["credit_reversal"]
    )
    credit_side = (
        documents["credit"]
        + manual["adjustment_credit"]
        + manual["debit_reversal"]
        + assessment.previous_balance
    )
    # Guia Prático, E110 campos 11 a 14: the deductions are reported in full
    # "ainda que no campo VL_SLD_APURADO tenha como resultado o valor zero";
    # what they exceed of the balance due goes to the credit balance carried
    # forward, which also takes the absolute value of a negative expression.
    balance = debit_side - credit_side
    assessed = max(balance, 0.0)
    deductions = assessment.deduction_total
    payable = assessed - deductions
    if balance >= 0:
        carried = max(-payable, 0.0)
    else:
        carried = -balance + deductions
    return {
        "VL_TOT_DEBITOS": documents["debit"],
        # Debit adjustments coming from the fiscal document itself
        # (C197/D197) are not written yet: once they are, they belong here
        # rather than in field 04, which is the assessment adjustment.
        "VL_AJ_DEBITOS": 0.0,
        "VL_TOT_AJ_DEBITOS": manual["adjustment_debit"],
        "VL_ESTORNOS_CRED": manual["credit_reversal"],
        "VL_TOT_CREDITOS": documents["credit"],
        "VL_AJ_CREDITOS": 0.0,
        "VL_TOT_AJ_CREDITOS": manual["adjustment_credit"],
        "VL_ESTORNOS_DEB": manual["debit_reversal"],
        "VL_SLD_CREDOR_ANT": assessment.previous_balance,
        "VL_SLD_APURADO": assessed,
        "VL_TOT_DED": deductions,
        "VL_ICMS_RECOLHER": max(payable, 0.0),
        "VL_SLD_CREDOR_TRANSPORTAR": carried,
        "DEB_ESP": assessment.special_debit_total + documents["extemporaneous"],
    }


def accounting_divergence(env, declaration, assessment):
    """Debits and credits where the accounting disagrees with the documents.

    The assessment reads the tax lines of the accounting; the file reads the
    documents. When they differ (an entry whose ICMS went to cost, an invoice
    whose tax line was edited), the file is still right, but the accounting
    is not, and somebody has to fix it. Returns the differences, rounded.
    """
    documents = icms_document_totals(env, declaration)
    differences = {}
    for kind, booked in (
        ("debit", assessment.debit_total),
        ("credit", assessment.credit_total),
    ):
        difference = round(documents[kind] - booked, 2)
        if difference:
            differences[kind] = (round(documents[kind], 2), round(booked, 2))
    return differences


# CSOSN of a Simples Nacional supplier -> CST_ICMS on the declarant's side.
# Guia Prático, Tabela 4.3.1 (Seção 2): the CSOSN is only for issuing; the
# entry is written with the CST "sob o enfoque do declarante" (C170 campo 10):
# goods whose ICMS-ST was charged before become 60, the rest 90.
CSOSN_TO_CST = {"201": "60", "202": "60", "203": "60", "500": "60"}


def icms_cst(line):
    """CST_ICMS of C170/C190: origin plus the two digits of Tabela B."""
    code = line.icms_cst_id.code or "00"
    if len(code) == 3:  # CSOSN
        code = CSOSN_TO_CST.get(code, "90")
    return f"{line.icms_origin or '0'}{code}"


def values_query(rows, columns):
    """SQL returning `rows` (tuples) as a result set, for `_odoo_query`.

    The registers whose grouping needs Python (a CST mapped from the CSOSN,
    a value read from non stored fields) still go through the query path of
    the base this way.
    """
    if not rows:
        return "SELECT 1 WHERE FALSE", []
    placeholders = ", ".join(["(" + ", ".join(["%s"] * len(columns)) + ")"] * len(rows))
    params = [value for row in rows for value in row]
    return (
        f"SELECT * FROM (VALUES {placeholders}) AS t({', '.join(columns)})",
        params,
    )


def has_difal(document, company):
    """Interstate operation to a final consumer with DIFAL/FCP (C101)."""
    return document.partner_id.state_id != company.state_id and bool(
        document.amount_icms_destination_value
        or document.amount_icms_origin_value
        or document.amount_icmsfcp_value
    )


def difal_by_uf(env, declaration):
    """DIFAL/FCP of the period per UF, from the C101 documents (E300/E310).

    Guia Prático, E310 campos 04/06/07/08 (layout from 2017): for the UF of a
    destination the debits are the VL_ICMS_UF_DEST/VL_FCP_UF_DEST of the exits
    and the credits the VL_ICMS_UF_REM/VL_FCP_UF_DEST of the returns; for the
    UF of the 0000 the debits are the VL_ICMS_UF_REM of the exits and the
    credits the VL_ICMS_UF_DEST of the entries.
    """
    company = declaration.company_id
    own_uf = company.state_id.code
    totals = {}

    def bucket(uf):
        return totals.setdefault(
            uf, {"deb": 0.0, "cred": 0.0, "deb_fcp": 0.0, "cred_fcp": 0.0}
        )

    for document in valued_documents(env, declaration):
        if not has_difal(document, company):
            continue
        uf = document.partner_id.state_id.code
        dest = document.amount_icms_destination_value
        rem = document.amount_icms_origin_value
        fcp = document.amount_icmsfcp_value
        if document.fiscal_operation_type == FISCAL_IN:
            bucket(uf)["cred"] += rem
            bucket(uf)["cred_fcp"] += fcp
            if dest:
                bucket(own_uf)["cred"] += dest
        else:
            bucket(uf)["deb"] += dest
            bucket(uf)["deb_fcp"] += fcp
            if rem:
                bucket(own_uf)["deb"] += rem
    return totals


def difal_assessment(bucket):
    """E310 fields from the period totals of one UF (no prior balance)."""
    difal = bucket["deb"] - bucket["cred"]
    fcp = bucket["deb_fcp"] - bucket["cred_fcp"]
    moved = any(bucket.values())
    return {
        "IND_MOV_FCP_DIFAL": "1" if moved else "0",
        "VL_SLD_CRED_ANT_DIFAL": 0.0,
        "VL_TOT_DEBITOS_DIFAL": bucket["deb"],
        "VL_OUT_DEB_DIFAL": 0.0,
        "VL_TOT_CREDITOS_DIFAL": bucket["cred"],
        "VL_OUT_CRED_DIFAL": 0.0,
        "VL_SLD_DEV_ANT_DIFAL": max(difal, 0.0),
        "VL_DEDUCOES_DIFAL": 0.0,
        "VL_RECOL_DIFAL": max(difal, 0.0),
        "VL_SLD_CRED_TRANSPORTAR_DIFAL": max(-difal, 0.0),
        "DEB_ESP_DIFAL": 0.0,
        "VL_SLD_CRED_ANT_FCP": 0.0,
        "VL_TOT_DEB_FCP": bucket["deb_fcp"],
        "VL_OUT_DEB_FCP": 0.0,
        "VL_TOT_CRED_FCP": bucket["cred_fcp"],
        "VL_OUT_CRED_FCP": 0.0,
        "VL_SLD_DEV_ANT_FCP": max(fcp, 0.0),
        "VL_DEDUCOES_FCP": 0.0,
        "VL_RECOL_FCP": max(fcp, 0.0),
        "VL_SLD_CRED_TRANSPORTAR_FCP": max(-fcp, 0.0),
        "DEB_ESP_FCP": 0,
    }


def participant_code(partner):
    """COD_PART shared by 0150 and the documents (C100, C500, D100...).

    The CNPJ/CPF identifies a Brazilian participant; a foreign one (the
    supplier of an import) has neither, and an empty code makes the PVA
    refuse both the 0150 and the document pointing at it.
    """
    return partner.cnpj_cpf_stripped or f"P{partner.id}"


def nature_code(operation):
    """COD_NAT of 0400/C170: up to 10 characters (Guia Prático, 0400)."""
    code = (operation.code or "").strip()
    return code if code and len(code) <= 10 else str(operation.id)


def item_code(product):
    """COD_ITEM shared by 0200, C170 and the other item registers."""
    return product.default_code or str(product.id)


def local_date(record, value):
    """Calendar date in Brazil of a UTC Datetime (DT_DOC, DT_E_S).

    Assigning the Datetime to a Date field keeps the UTC day: a note issued on
    the 30th at 22:00 would be dated the 1st of the next month, beyond DT_FIN.
    """
    if not value:
        return False
    tz = record.env.user.tz or "America/Sao_Paulo"
    return fields.Datetime.context_timestamp(record.with_context(tz=tz), value).date()


def reform_taxes_outside_total(lines):
    """CBS and IBS of the lines that the document total ADDS on top.

    Guia Prático 3.2.4, Seção 10 and C100 field 12: in 2026 the EFD ICMS/IPI
    total of the document (C100.VL_DOC) and the value of the operation
    (C190.VL_OPR) never include CBS, IBS or IS. A tax configured as included in
    the price is already outside the sum `fiscal_amount_total` makes; only the
    ones added on top have to be taken back out.
    """
    total = 0.0
    for line in lines:
        for domain in ("cbs", "ibs"):
            tax = line[f"{domain}_tax_id"]
            if tax and not tax.tax_group_id.tax_include:
                total += line[f"{domain}_value"]
    return total


def has_only_reform_taxes(document):
    """True when the document carries CBS/IBS and no ICMS nor IPI at all.

    Guia Prático 3.2.4, C100 (3.2.2, item 2): such a document is not bookkept
    in the EFD ICMS/IPI.
    """
    lines = document.fiscal_line_ids
    has_new = any(line.cbs_tax_id or line.ibs_tax_id for line in lines)
    has_old = any(
        line.icms_cst_id or line.icms_tax_id or line.ipi_cst_id or line.ipi_tax_id
        for line in lines
    )
    return has_new and not has_old


