class RegistroC100(models.Model):
    """Documento - Nota Fiscal (código 01, 1B, 04, 55, 65)."""

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_icms_ipi.c100"
    _inherit = "l10n_br_sped.efd_icms_ipi.20.c100"
    _odoo_model = "l10n_br_fiscal.document"

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        Document = self.env["l10n_br_fiscal.document"]
        models_c100 = ("01", "1B", "04", "55", "65")
        start, end = period_bounds_utc(self.env, declaration.DT_INI, declaration.DT_FIN)
        documents = Document.search(
            [
                ("id", "in", declaration.fiscal_document_ids.ids),
                ("document_type_id.code", "in", models_c100),
            ]
        )
        # Guia Prático, C100 campo 11: an ENTRY belongs to the period of its
        # entry date (DT_E_S), which the PVA requires to be within the 0000.
        # An entry issued in the period and received after it goes to the
        # next file; one issued before and received in it comes into this one.
        entries_late = documents.filtered(
            lambda doc: doc.fiscal_operation_type == FISCAL_IN
            and doc.date_in_out
            and doc.date_in_out >= end
        )
        entries_early = Document.search(
            [
                ("company_id", "=", declaration.company_id.id),
                ("document_type_id.code", "in", models_c100),
                ("state_edoc", "in", ("autorizada", "cancelada", "denegada")),
                ("fiscal_operation_type", "=", FISCAL_IN),
                ("document_date", "<", start),
                ("date_in_out", ">=", start),
                ("date_in_out", "<", end),
            ]
        )
        documents = (documents - entries_late) | entries_early
        # Guia Prático 3.2.4, C100: a document that carries only the new
        # taxes of the reform (CBS/IBS/IS) and no ICMS nor IPI is not bookkept;
        # nor, since January 2023, a denied NF-e or a voided number (codes 04
        # and 05 of Tabela 4.1.2 were discontinued; the PVA refuses them).
        documents = documents.filtered(
            lambda doc: not has_only_reform_taxes(doc)
            and doc.state_edoc not in ("denegada", "inutilizada")
        )
        return [("id", "in", documents.ids)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        situation = cod_sit(record)
        dt_e_s = local_date(record, record.date_in_out)
        if record.fiscal_operation_type == FISCAL_IN:
            ind_oper = "0"
        else:
            ind_oper = "1"
        if record.issuer == DOCUMENT_ISSUER_COMPANY:
            ind_emit = "0"
        else:
            ind_emit = "1"

        # A partir de janeiro de 2023, os códigos de situação de documento 04 (NF-e ou CT-e denegado) e
        # 05 (NF-e ou CT-e Numeração inutilizada) da tabela 4.1.2 - Tabela Situação do Documento serão descontinuados.
        # elif nfe.state_edoc == "denegada" and nfe.edoc_purpose == "1":
        #     cod_sit = "04"
        # elif nfe.state_edoc == "inutilizada":
        #     cod_sit = "05"
        #     registro_c100.SER = ""
        #     registro_c100.CHV_NFE = ""
        # if nfe.emissao_doc == '1' and not nfe.state == 'cancel' \
        #     and nfe.chave_nfe[6:20] != \
        #     self.limpa_formatacao(nfe.partner_id.company_id.cnpj_cpf):
        #     cod_sit = '08'

        ind_pgto = "1"  # TODO ATS-TI code is commented as follow:
        # if nfe.nfe40_pag:
        #     if len(nfe.duplicata_ids) == 1:
        #         if nfe.duplicata_ids.data_vencimento == nfe.data_agendada:
        #             ind_pgto = '0'
        #         else:
        #             ind_pgto = '1'
        #     else:
        #         ind_pgto = '1'
        # else:
        #     ind_pgto = '2'

        if situation in COD_SIT_WITHOUT_VALUES:
            # Guia Prático, C100, Exceção 1: cancelled, denied or voided
            # documents carry only the identification, every other field
            # empty, and no child register. The key is left out only for a
            # voided number (05), which never had one.
            return {
                "IND_OPER": ind_oper,
                "IND_EMIT": ind_emit,
                "COD_MOD": record.document_type_id.code,
                "COD_SIT": situation,
                "SER": record.document_serie,
                "NUM_DOC": misc.punctuation_rm(str(record.document_number)),
                "CHV_NFE": record.document_key if situation != "05" else "",
            }

        return {
            "IND_OPER": ind_oper,
            "IND_EMIT": ind_emit,
            "COD_PART": participant_code(record.partner_id),
            "COD_MOD": record.document_type_id.code,
            "COD_SIT": situation,
            "SER": record.document_serie,
            "NUM_DOC": misc.punctuation_rm(str(record.document_number)),
            # CNPJ and key are text since layout 020 (NT 2025.001, alphanumeric
            # CNPJ): written as they are, never as a number.
            "CHV_NFE": record.document_key,
            "DT_DOC": local_date(record, record.document_date),
            # Guia Prático, C100 campo 11: an exit whose date is after the
            # period end leaves the field empty
            "DT_E_S": dt_e_s if not (dt_e_s and dt_e_s > declaration.DT_FIN) else False,
            # Guia Prático 3.2.4, Seção 10 and C100 field 12: in 2026 the
            # total of the document leaves CBS, IBS and IS out.
            "VL_DOC": record.fiscal_amount_total
            - reform_taxes_outside_total(record.fiscal_line_ids),
            "IND_PGTO": ind_pgto,
            "VL_DESC": record.amount_discount_value,
            # the sum of the C170 field 38, which the PVA compares it with
            "VL_ABAT_NT": sum(
                record.fiscal_line_ids.mapped("financial_discount_value")
            ),
            "VL_MERC": record.amount_price_gross,
            # 9 = sem frete when the NF-e module (modFrete) is not there or
            # the document has no transport mode; never the text "False".
            "IND_FRT": str(getattr(record, "nfe40_modFrete", "") or "9"),
            "VL_FRT": record.amount_freight_value,
            "VL_SEG": record.amount_insurance_value,
            "VL_OUT_DA": record.amount_other_value,
            "VL_BC_ICMS": record.amount_icms_base,
            "VL_ICMS": record.amount_icms_value,
            "VL_BC_ICMS_ST": record.amount_icmsst_base,
            "VL_ICMS_ST": record.amount_icmsst_value,
            "VL_IPI": record.amount_ipi_value,
            "VL_PIS": record.amount_pis_value,
            "VL_COFINS": record.amount_cofins_value,
            # "VL_PIS_ST": record.amount_pisst_value,  # don't we have a field?
            # "VL_COFINS_ST": record.amount_cofinsst_value,  # idem
        }


class RegistroC101(models.Model):
    """Informação complementar dos documentos fiscais quando das operações
    interestaduais destinadas."""

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_icms_ipi.c101"
    _inherit = "l10n_br_sped.efd_icms_ipi.20.c101"
    # without a model the base writes one C101 under EVERY C100, ignoring
    # the domain below
    _odoo_model = "l10n_br_fiscal.document"

    VL_FCP_UF_DEST = fields.Monetary(
        out_required=True, currency_field="brl_currency_id"
    )
    VL_ICMS_UF_DEST = fields.Monetary(
        out_required=True, currency_field="brl_currency_id"
    )
    VL_ICMS_UF_REM = fields.Monetary(
        out_required=True, currency_field="brl_currency_id"
    )

    @api.model
    def _odoo_domain(self, parent_record, declaration):
        # Only the interstate operation to a final consumer with DIFAL (EC
        # 87/2015): the PVA refuses a C101 whose participant is in the UF of
        # the 0000, and it used to come out for every document.
        if not has_difal(parent_record, declaration.company_id):
            return [(0, "=", 1)]
        return [("id", "=", parent_record.id)]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        return {
            "VL_FCP_UF_DEST": parent_record.amount_icmsfcp_value or 0.0,
            "VL_ICMS_UF_DEST": parent_record.amount_icms_destination_value or 0.0,
            "VL_ICMS_UF_REM": parent_record.amount_icms_origin_value or 0.0,
        }


