class RegistroC120(models.Model):
    """Complemento de Documento - Operações de Importação (códigos 01 e 55)."""

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_icms_ipi.c120"
    _inherit = "l10n_br_sped.efd_icms_ipi.20.c120"

    @api.model
    def _odoo_query(self, parent_record, declaration):
        """One C120 per import declaration of an ENTRY document.

        The declarations live in the `<DI>` group of the NF-e items
        (`nfe.40.di`, from l10n_br_nfe); without that module there is nothing
        to report and the query returns no row.
        """
        if (
            "nfe.40.di" not in self.env
            or parent_record.fiscal_operation_type != FISCAL_IN
        ):
            return "SELECT 1 WHERE FALSE", []
        query = """
            SELECT DISTINCT di."nfe40_nDI" AS num_doc_imp
            FROM nfe_40_di di
            JOIN l10n_br_fiscal_document_line fdl
                ON fdl.id = di."nfe40_DI_prod_id"
            WHERE fdl.document_id = %s
              AND COALESCE(di."nfe40_nDI", '') != ''
            ORDER BY 1
        """
        return query, [parent_record.id]

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        number = (record.get("num_doc_imp") or "").strip()
        return {
            "COD_DOC_IMP": import_document_code(number),
            "NUM_DOC_IMP": number,
            # Campos 04 e 05: dispensados para quem entrega a EFD-Contribuições
            # do mesmo período (Guia Prático, C120); conteúdo vazio.
            "PIS_IMP": 0.0,
            "COFINS_IMP": 0.0,
            "NUM_ACDRAW": "",
        }


