class RegistroC190(models.Model):
    """Registro Analítico do Documento."""

    _description = textwrap.dedent(f"    {__doc__}")
    _name = "l10n_br_sped.efd_icms_ipi.c190"
    _inherit = "l10n_br_sped.efd_icms_ipi.20.c190"

    # The descriptor marks fields 5 to 11 obrigatorio=1: a zero must be
    # written "0", never blank, or the PVA refuses the record with "campo
    # obrigatorio". Declared at the mapping layer, as everywhere else.
    VL_OPR = fields.Monetary(out_required=True, currency_field="brl_currency_id")
    VL_BC_ICMS = fields.Monetary(out_required=True, currency_field="brl_currency_id")
    VL_ICMS = fields.Monetary(out_required=True, currency_field="brl_currency_id")
    VL_BC_ICMS_ST = fields.Monetary(out_required=True, currency_field="brl_currency_id")
    VL_ICMS_ST = fields.Monetary(out_required=True, currency_field="brl_currency_id")
    VL_RED_BC = fields.Monetary(out_required=True, currency_field="brl_currency_id")
    VL_IPI = fields.Monetary(out_required=True, currency_field="brl_currency_id")

    @api.model
    def _odoo_query(self, parent_record, declaration):
        # Guia Prático, C190: one record per CST_ICMS + CFOP + ALIQ_ICMS. The
        # CST is the declarant's (`icms_cst`, a CSOSN becomes 60/90), so the
        # grouping is done here and handed to the base as a VALUES query.
        groups = {}
        for line in parent_record.fiscal_line_ids:
            key = (icms_cst(line), line.cfop_id.code or "", line.icms_percent or 0.0)
            groups.setdefault(key, []).append(line.id)
        rows = [(cst, cfop, aliq, ids) for (cst, cfop, aliq), ids in groups.items()]
        return values_query(sorted(rows), ("cst_icms", "cfop", "aliq_icms", "line_ids"))

    @api.model
    def _vl_red_bc(self, record, lines):
        """Amount left out of the ICMS base by a base reduction.

        Guia Prático, C190 campo 10: greater than zero when CST ends in 20 or
        70 (the PVA warns otherwise); the value of the operation minus the
        ICMS base and what is added on top of the goods (ST and IPI).
        """
        if (record.get("cst_icms") or "")[-2:] not in ("20", "70"):
            return 0.0
        reduced = (
            self._vl_opr(record["line_ids"])
            - sum(lines.mapped("icms_base"))
            - sum(lines.mapped("icmsst_value"))
            - sum(lines.mapped("ipi_value"))
        )
        return max(reduced, 0.0)

    @api.model
    def _vl_opr(self, line_ids):
        """Value of the operation of the CST/CFOP/rate group.

        The total of each line as the document totals it (products, minus
        discount and relief, plus freight, insurance, other expenses, ICMS-ST
        and IPI) and, by Guia Prático 3.2.4 Seção 10, never the CBS, IBS or
        IS of the reform. Read from the ORM because the line totals are not
        stored: the former `SUM(amount_tax_not_included)` summed only the
        taxes added on top, not the operation.
        """
        lines = self.env["l10n_br_fiscal.document.line"].browse(line_ids)
        return sum(lines.mapped("fiscal_amount_total")) - reform_taxes_outside_total(
            lines
        )

    @api.model
    def _map_from_odoo(self, record, parent_record, declaration, index=0):
        lines = self.env["l10n_br_fiscal.document.line"].browse(record["line_ids"])
        return {
            "CST_ICMS": record.get("cst_icms") or "",
            "CFOP": record.get("cfop") or "",
            "ALIQ_ICMS": float(record.get("aliq_icms") or 0.0),
            "VL_OPR": self._vl_opr(record["line_ids"]),
            "VL_BC_ICMS": sum(lines.mapped("icms_base")),
            "VL_ICMS": sum(lines.mapped("icms_value")),
            "VL_BC_ICMS_ST": sum(lines.mapped("icmsst_base")),
            "VL_ICMS_ST": sum(lines.mapped("icmsst_value")),
            "VL_RED_BC": self._vl_red_bc(record, lines),
            "VL_IPI": sum(lines.mapped("ipi_value")),
            "COD_OBS": "",
        }


